from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session
from typing import List, Optional
import uuid

from app.database import get_db
from app.schemas.seat import SeatResponse, SeatAvailability
from app.models.seat import Seat, SeatStatus
from app.core.logging import get_logger

logger = get_logger(__name__)
router = APIRouter()


@router.get(
    "/events/{event_id}/seats",
    response_model=List[SeatResponse],
    summary="Get event seats",
    description="Retrieve all seats for a specific event"
)
async def get_event_seats(
        event_id: uuid.UUID,
        status_filter: Optional[SeatStatus] = Query(None, description="Filter by seat status"),
        db: Session = Depends(get_db)
):
    """
    Get all seats for an event with optional status filtering.

    - **event_id**: UUID of the event
    - **status_filter**: Optional filter by seat status (available, reserved, booked, locked)
    """
    query = db.query(Seat).filter(Seat.event_id == event_id)

    if status_filter:
        query = query.filter(Seat.status == status_filter)

    seats = query.order_by(
        Seat.seat_section,
        Seat.seat_row,
        Seat.seat_number
    ).all()

    return seats


@router.get(
    "/events/{event_id}/seats/availability",
    response_model=List[SeatAvailability],
    summary="Get seat availability",
    description="Get simplified availability status for all seats"
)
async def get_seat_availability(
        event_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Get simplified availability information for all seats in an event.
    Returns only essential information for seat selection UI.
    """
    seats = db.query(Seat).filter(Seat.event_id == event_id).all()

    availability = []
    for seat in seats:
        availability.append(
            SeatAvailability(
                seat_id=seat.seat_id,
                seat_number=seat.seat_number,
                status=seat.status.value,
                price=seat.price,
                is_available=seat.status == SeatStatus.AVAILABLE
            )
        )

    return availability


@router.get(
    "/{seat_id}",
    response_model=SeatResponse,
    summary="Get seat details",
    description="Get detailed information about a specific seat"
)
async def get_seat(
        seat_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Get details of a specific seat.
    """
    seat = db.query(Seat).filter(Seat.seat_id == seat_id).first()

    if not seat:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Seat not found"
        )

    return seat


@router.get(
    "/{seat_id}/status",
    summary="Check seat status",
    description="Quick check of seat availability status"
)
async def check_seat_status(
        seat_id: uuid.UUID,
        db: Session = Depends(get_db)
):
    """
    Quick check if a seat is available for booking.
    """
    seat = db.query(Seat).filter(Seat.seat_id == seat_id).first()

    if not seat:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail="Seat not found"
        )

    return {
        "seat_id": str(seat.seat_id),
        "status": seat.status.value,
        "is_available": seat.status == SeatStatus.AVAILABLE,
        "reserved_until": seat.reserved_until.isoformat() if seat.reserved_until else None
    }
